void compute_f (const int n,
                const float *x,
                const float *y,
                      float *r)
{
  #pragma omp target teams distribute parallel for thread_limit(256)
  for (int i = 0; i < n; i++) {
    const float vy = y[i];
    const float vx = x[i];
    r[i] = safe_atan2f< 3>(vy, vx) +
           safe_atan2f< 5>(vy, vx) +
           safe_atan2f< 7>(vy, vx) +
           safe_atan2f< 9>(vy, vx) +
           safe_atan2f<11>(vy, vx) +
           safe_atan2f<13>(vy, vx) +
           safe_atan2f<15>(vy, vx);
  }
}


void compute_s (const int n,
                const float *x,
                const float *y,
                      short *r)
{
  #pragma omp target teams distribute parallel for thread_limit(256)
  for (int i = 0; i < n; i++) {
    const float vy = y[i];
    const float vx = x[i];
    r[i] = unsafe_atan2s< 3>(vy, vx) +
           unsafe_atan2s< 5>(vy, vx) +
           unsafe_atan2s< 7>(vy, vx) +
           unsafe_atan2s< 9>(vy, vx);
  }
}


void compute_i (const int n,
                const float *x,
                const float *y,
                      int *r)
{
  #pragma omp target teams distribute parallel for thread_limit(256)
  for (int i = 0; i < n; i++) {
    const float vy = y[i];
    const float vx = x[i];
    r[i] = unsafe_atan2i< 3>(vy, vx) +
           unsafe_atan2i< 5>(vy, vx) +
           unsafe_atan2i< 7>(vy, vx) +
           unsafe_atan2i< 9>(vy, vx) +
           unsafe_atan2i<11>(vy, vx) +
           unsafe_atan2i<13>(vy, vx) +
           unsafe_atan2i<15>(vy, vx);
  }
}

void reference_f (const int n,
                  const float *x,
                  const float *y,
                        float *r)
{
  for (int i = 0; i < n; i++) {
    const float vy = y[i];
    const float vx = x[i];
    r[i] = safe_atan2f< 3>(vy, vx) +
           safe_atan2f< 5>(vy, vx) +
           safe_atan2f< 7>(vy, vx) +
           safe_atan2f< 9>(vy, vx) +
           safe_atan2f<11>(vy, vx) +
           safe_atan2f<13>(vy, vx) +
           safe_atan2f<15>(vy, vx);
  }
}

void reference_s (const int n,
                  const float *x,
                  const float *y,
                        short *r)
{
  for (int i = 0; i < n; i++) {
    const float vy = y[i];
    const float vx = x[i];
    r[i] = unsafe_atan2s< 3>(vy, vx) +
           unsafe_atan2s< 5>(vy, vx) +
